# Pulumi TypeScript: `AppInfra` ComponentResource

## Project structure

```
pulumi-app/
├── Pulumi.yaml
├── Pulumi.dev.yaml
├── Pulumi.prod.yaml
├── index.ts
├── src/
│   ├── component.ts
│   ├── config.ts
│   └── secret.ts
```

---

## `src/config.ts` — environment config

```typescript
import * as pulumi from "@pulumi/pulumi";

export interface AppConfig {
  environment: "dev" | "prod";
  region: string;
  replicaRegion?: string;      // prod only
  bucketName: string;
  dbName: string;
  dbInstanceClass: string;
  dbMultiAz: boolean;
  dbStorageEncrypted: boolean;
}

export function getConfig(): AppConfig {
  const cfg = new pulumi.Config();
  const env = (pulumi.getStack() === "prod" ? "prod" : "dev") as "dev" | "prod";

  if (env === "prod") {
    return {
      environment: env,
      region: cfg.get("aws:region") ?? "us-east-1",
      replicaRegion: "us-west-2",
      bucketName: cfg.require("bucketName"),
      dbName: cfg.require("dbName"),
      dbInstanceClass: "db.t3.medium",
      dbMultiAz: true,
      dbStorageEncrypted: true,
    };
  }
  return {
    environment: env,
    region: cfg.get("aws:region") ?? "us-east-1",
    bucketName: cfg.require("bucketName"),
    dbName: cfg.require("dbName"),
    dbInstanceClass: "db.t3.micro",
    dbMultiAz: false,
    dbStorageEncrypted: false,
  };
}
```

