## `src/component.ts` — the ComponentResource

```typescript
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";
import { AppConfig } from "./config";

export interface AppInfraArgs {
  config: AppConfig;
  /** PostgreSQL master password — must be a secret from the stack config */
  dbPassword: pulumi.Output<string>;
}

export class AppInfra extends pulumi.ComponentResource {
  public readonly bucket: aws.s3.BucketV2;
  public readonly database: aws.rds.Instance;
  public readonly serviceRole: aws.iam.Role;
  public readonly dbSecret: pulumi.Output<string>;

  constructor(name: string, args: AppInfraArgs, opts?: pulumi.ComponentResourceOptions) {
    super("mycompany:AppInfra", name, {}, opts);
    const cfg = args.config;
    const defaultOpts = { parent: this };

    // ---------- 1. S3 bucket ----------
    const bucket = new aws.s3.BucketV2(`${name}-assets`, {
      bucket: cfg.bucketName,
    }, defaultOpts);

    new aws.s3.BucketVersioningV2(`${name}-assets-versioning`, {
      bucket: bucket.id,
      versioningConfiguration: { status: "Enabled" },
    }, defaultOpts);

    new aws.s3.BucketServerSideEncryptionConfigurationV2(`${name}-assets-sse`, {
      bucket: bucket.id,
      rules: [{
        applyServerSideEncryptionByDefault: { sseAlgorithm: "AES256" },
      }],
    }, defaultOpts);

    new aws.s3.BucketPublicAccessBlock(`${name}-assets-pab`, {
      bucket: bucket.id,
      blockPublicAcls: true,
      blockPublicPolicy: true,
      ignorePublicAcls: true,
      restrictPublicBuckets: true,
    }, defaultOpts);

    if (cfg.replicaRegion) {
      // Prod: cross-region replication
      const replicaBucket = new aws.s3.BucketV2(`${name}-assets-replica`, {
        bucket: `${cfg.bucketName}-replica`,
      }, defaultOpts);
      new aws.s3.BucketVersioningV2(`${name}-assets-replica-versioning`, {
        bucket: replicaBucket.id,
        versioningConfiguration: { status: "Enabled" },
      }, defaultOpts);

      const replicationRole = new aws.iam.Role(`${name}-repl-role`, {
        assumeRolePolicy: JSON.stringify({
          Version: "2012-10-17",
          Statement: [{
            Effect: "Allow",
            Principal: { Service: "s3.amazonaws.com" },
            Action: "sts:AssumeRole",
          }],
        }),
      }, defaultOpts);

      new aws.iam.RolePolicy(`${name}-repl-policy`, {
        role: replicationRole.id,
        policy: JSON.stringify({
          Version: "2012-10-17",
          Statement: [{
            Effect: "Allow",
            Action: ["s3:GetObjectVersionForReplication", "s3:GetObjectVersionAcl"],
            Resource: [bucket.arn],
          }, {
            Effect: "Allow",
            Action: ["s3:ReplicateObject", "s3:ReplicateDelete"],
            Resource: [`${replicaBucket.arn}/*`],  // scoped, no wildcard actions
          }],
        }),
      }, defaultOpts);

      new aws.s3.BucketReplicationConfig(`${name}-assets-replconfig`, {
        bucket: bucket.id,
        role: replicationRole.arn,
        rules: [{
          id: "all",
          status: "Enabled",
          filter: {},
          deleteMarkerReplication: { status: "Disabled" },
          destinations: [{
            bucket: replicaBucket.arn,
            storageClass: "STANDARD_IA",
          }],
        }],
      }, { ...defaultOpts, dependsOn: [replicaBucket] });
    }

    this.bucket = bucket;

    // ---------- 2. RDS PostgreSQL ----------
    this.database = new aws.rds.Instance(`${name}-db`, {
      identifier: cfg.dbName,
      engine: "postgres",
      engineVersion: "16.3",
      instanceClass: cfg.dbInstanceClass,
      allocatedStorage: cfg.environment === "prod" ? 100 : 20,
      dbName: cfg.dbName,
      username: "appadmin",
      password: args.dbPassword,
      multiAz: cfg.dbMultiAz,
      storageEncrypted: cfg.dbStorageEncrypted,
      deletionProtection: true,        // always on
      backupRetentionPeriod: 14,       // >= 7
      publiclyAccessible: false,
      skipFinalSnapshot: false,
      finalSnapshotIdentifier: `${cfg.dbName}-final`,
    }, defaultOpts);

    // Secret via stack-native mechanism: Pulumi secret output → deploy-time
    // injection through aws.secretsmanager for the app to consume.
    const smSecret = new aws.secretsmanager.Secret(`${name}-db-secret`, {
      name: `/${cfg.environment}/${cfg.dbName}/connection`,
    }, defaultOpts);

    new aws.secretsmanager.SecretVersion(`${name}-db-secret-value`, {
      secretId: smSecret.id,
      secretString: pulumi.jsonStringify({
        host: this.database.address,
        port: this.database.port,
        dbname: cfg.dbName,
        username: "appadmin",
        password: args.dbPassword,
      }).apply(s => pulumi.secret(s)),
    }, defaultOpts);

    this.dbSecret = smSecret.arn;

    // ---------- 3. IAM role for service accounts ----------
    // Dev: IAM user with programmatic access; Prod: OIDC trust role, least privilege.
    if (cfg.environment === "prod") {
      this.serviceRole = new aws.iam.Role(`${name}-service-role`, {
        description: "Least-privilege OIDC trust role for prod workloads",
        assumeRolePolicy: JSON.stringify({
          Version: "2012-10-17",
          Statement: [{
            Effect: "Allow",
            Principal: {
              Federated: `arn:aws:iam::${(new aws.getCallerIdentity().then(i => i.accountId))}:oidc-provider/oidc.eks.amazonaws.com`,
            },
            Action: "sts:AssumeRoleWithWebIdentity",
            Condition: {
              StringEquals: {
                "oidc.eks.amazonaws.com:sub": `system:serviceaccount:default:${cfg.dbName}-sa`,
              },
            },
          }],
        }),
      }, defaultOpts);

      new aws.iam.RolePolicy(`${name}-service-policy`, {
        role: this.serviceRole.id,
        policy: JSON.stringify({
          Version: "2012-10-17",
          Statement: [{
            Sid: "ReadOwnBucket",
            Effect: "Allow",
            Action: [
              "s3:GetObject", "s3:GetObjectVersion", "s3:ListBucket",
              "s3:PutObject", "s3:DeleteObject",
            ],
            Resource: [bucket.arn, `${bucket.arn}/*`],
          }, {
            Sid: "ReadDbSecret",
            Effect: "Allow",
            Action: ["secretsmanager:GetSecretValue"],
            Resource: [smSecret.arn],
          }],
        }),
      }, defaultOpts);
    } else {
      const user = new aws.iam.User(`${name}-svc-user`, {
        name: `${name}-service-account`,
      }, defaultOpts);
      new aws.iam.AccessKey(`${name}-svc-key`, { user: user.name },
        { ...defaultOpts, additionalSecretOutputs: ["secret"] });

      this.serviceRole = new aws.iam.Role(`${name}-service-role`, {
        assumeRolePolicy: JSON.stringify({
          Version: "2012-10-17",
          Statement: [{
            Effect: "Allow",
            Principal: { Service: "ec2.amazonaws.com" },
            Action: "sts:AssumeRole",
          }],
        }),
      }, defaultOpts);

      new aws.iam.UserPolicyAttachment(`${name}-svc-policy-attach`, {
        user: user.name,
        policyArn: new aws.iam.Policy(`${name}-svc-policy`, {
          policy: JSON.stringify({
            Version: "2012-10-17",
            Statement: [{
              Effect: "Allow",
              Action: ["s3:*"],   // dev only — relaxed for iteration speed
              Resource: [bucket.arn, `${bucket.arn}/*`],
            }],
          }),
        }).arn,
      }, defaultOpts);
    }

    this.registerOutputs({
      bucketArn: bucket.arn,
      dbEndpoint: this.database.address,
      dbSecretArn: this.dbSecret,
      serviceRoleArn: this.serviceRole.arn,
    });
  }
}
```

## `index.ts` — program entry

```typescript
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";
import { getConfig } from "./src/config";
import { AppInfra } from "./src/component";

const config = getConfig();

// DB password provided as a stack secret:
//   pulumi config set --secret dbPassword
const cfg = new pulumi.Config();
const dbPassword = cfg.requireSecret("dbPassword");

const infra = new AppInfra(`myapp-${config.environment}`, { config, dbPassword });

export const bucketArn = infra.bucket.arn;
export const dbEndpoint = infra.database.address;
export const dbSecretArn = infra.dbSecret;
export const serviceRoleArn = infra.serviceRole.arn;
```

---

## Usage

```bash
pulumi stack init dev && pulumi config set --secret dbPassword '<pw>'
pulumi up

pulumi stack select prod && pulumi up   # independent state, prod untouched by dev
```

**How acceptance criteria map:**
1. Bucket: versioning + SSE + full public access block ✅
2. RDS: `deletionProtection: true`, 14-day backups, not publicly accessible ✅
3. Secret: DB password via `requireSecret` (encrypted in state, never plaintext); connection string written to Secrets Manager encrypted at rest ✅
4. IAM: prod uses scoped actions (no wildcards) and OIDC trust for least privilege; wide `s3:*` only in dev ✅
5/6/7: cluster + HTTPS handled per-spine elsewhere; each stack (`Pulumi.dev.yaml` / `Pulumi.prod.yaml`) has fully independent state files.
